package com.cowave.search.proxy.service

import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import org.apache.hc.core5.http.ContentType
import org.apache.hc.core5.http.io.entity.StringEntity
import org.elasticsearch.client.Request
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import jakarta.servlet.http.HttpServletRequest

@Service
class ProxyService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(ProxyService::class.java)

    /** 차단할 위험 패턴: path + method 조합 */
    private val blockedPatterns =
        listOf(
            Pair("PUT", "_cluster/settings"),
            Pair("POST", "_shutdown"),
            Pair("DELETE", "_all"),
        )

    fun proxy(
        clusterId: String,
        method: String,
        esPath: String,
        queryString: String?,
        body: String?,
    ): ProxyResult {
        // 위험 API 차단
        val upperMethod = method.uppercase()
        blockedPatterns.forEach { (blockedMethod, blockedPath) ->
            if (upperMethod == blockedMethod && esPath.contains(blockedPath)) {
                logger.warn("차단된 ES API 요청: {} {}", method, esPath)
                return ProxyResult(403, "application/json", """{"error":"forbidden","path":"$esPath"}""")
            }
        }

        val targetPath = if (queryString.isNullOrBlank()) esPath else "$esPath?$queryString"

        return runCatching {
            val restClient = clientFactory.getLowLevelClient(clusterId)
            val request = Request(method, targetPath)
            if (!body.isNullOrBlank()) {
                request.entity = StringEntity(body, ContentType.APPLICATION_JSON)
            }
            val response = restClient.performRequest(request)
            val responseBody = response.entity?.content?.bufferedReader()?.readText() ?: ""
            val statusCode = response.statusLine?.statusCode ?: 200
            val contentType =
                response.entity?.contentType ?: "application/json"
            ProxyResult(statusCode, contentType, responseBody)
        }.getOrElse { e ->
            logger.error("ES 프록시 오류 [{} {}]: {}", method, esPath, e.message)
            ProxyResult(500, "application/json", """{"error":"${e.message?.replace("\"", "'")}"}""")
        }
    }

    data class ProxyResult(
        val statusCode: Int,
        val contentType: String,
        val body: String,
    )
}

package com.cowave.search.common.elasticsearch

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.json.jackson.JacksonJsonpMapper
import co.elastic.clients.transport.rest5_client.Rest5ClientTransport
import co.elastic.clients.transport.rest5_client.low_level.Rest5Client
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.SerializationFeature
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule
import com.fasterxml.jackson.module.kotlin.kotlinModule
import jakarta.annotation.PreDestroy
import org.apache.hc.core5.http.Header
import org.apache.hc.core5.http.HttpHost
import org.apache.hc.core5.http.message.BasicHeader
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.util.Base64
import java.util.concurrent.ConcurrentHashMap

/**
 * 멀티 클러스터 Elasticsearch 클라이언트 팩토리.
 *
 * - ConcurrentHashMap 기반 클라이언트 캐시
 * - 클러스터 등록/삭제 시 캐시 갱신
 * - Basic 인증 및 ApiKey 인증 지원
 */
@Component
class ElasticsearchClientFactory {
    private val logger = LoggerFactory.getLogger(ElasticsearchClientFactory::class.java)

    private val clientCache = ConcurrentHashMap<String, CachedClusterClient>()

    private val jsonpMapper by lazy {
        val objectMapper =
            ObjectMapper()
                .registerModule(kotlinModule())
                .registerModule(JavaTimeModule())
                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
        JacksonJsonpMapper(objectMapper)
    }

    fun getClient(clusterId: String): ElasticsearchClient =
        clientCache[clusterId]?.esClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun getLowLevelClient(clusterId: String): Rest5Client =
        clientCache[clusterId]?.restClient
            ?: throw IllegalArgumentException("등록되지 않은 클러스터입니다: $clusterId")

    fun registerCluster(info: ClusterConnectionInfo) {
        val cached = buildCachedClient(info)
        clientCache[info.id] = cached
        logger.info("ES 클러스터 등록: {} ({}://{}:{})", info.id, info.scheme, info.host, info.port)
    }

    fun evictCluster(clusterId: String) {
        clientCache.remove(clusterId)?.let {
            runCatching { it.restClient.close() }
                .onFailure { e -> logger.warn("클러스터 클라이언트 종료 실패: $clusterId", e) }
        }
        logger.info("ES 클러스터 제거: {}", clusterId)
    }

    fun registeredClusterIds(): Set<String> = clientCache.keys.toSet()

    @PreDestroy
    fun closeAll() {
        clientCache.values.forEach { runCatching { it.restClient.close() } }
        clientCache.clear()
        logger.info("모든 ES 클러스터 클라이언트 종료 완료")
    }

    private fun buildCachedClient(info: ClusterConnectionInfo): CachedClusterClient {
        val host = HttpHost.create("${info.scheme}://${info.host}:${info.port}")
        val defaultHeaders = buildAuthHeaders(info)

        val restClient =
            Rest5Client
                .builder(host)
                .setDefaultHeaders(defaultHeaders)
                .build()

        val transport = Rest5ClientTransport(restClient, jsonpMapper)
        val esClient = ElasticsearchClient(transport)

        return CachedClusterClient(restClient, esClient)
    }

    private fun buildAuthHeaders(info: ClusterConnectionInfo): Array<Header> =
        when {
            !info.apiKey.isNullOrBlank() -> {
                arrayOf(BasicHeader("Authorization", "ApiKey ${info.apiKey}"))
            }
            !info.username.isNullOrBlank() && !info.password.isNullOrBlank() -> {
                val credentials = Base64.getEncoder().encodeToString("${info.username}:${info.password}".toByteArray())
                arrayOf(BasicHeader("Authorization", "Basic $credentials"))
            }
            else -> emptyArray()
        }

    private data class CachedClusterClient(
        val restClient: Rest5Client,
        val esClient: ElasticsearchClient,
    )

    data class ClusterConnectionInfo(
        val id: String,
        val scheme: String,
        val host: String,
        val port: Int,
        val username: String? = null,
        val password: String? = null,
        val apiKey: String? = null,
    )
}

package com.cowave.search.dynamicindex.controller

import com.cowave.search.dynamicindex.dto.BundleGroupResponse
import com.cowave.search.dynamicindex.dto.DynamicIndexInfoResponse
import com.cowave.search.dynamicindex.dto.QueueStateResponse
import com.cowave.search.dynamicindex.service.DynamicIndexService
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/dynamic-index")
class DynamicIndexController(
    private val dynamicIndexService: DynamicIndexService,
) {
    @GetMapping
    fun findAll(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<DynamicIndexInfoResponse> = dynamicIndexService.findAll()

    @GetMapping("/bundle")
    fun findByBundle(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<BundleGroupResponse> = dynamicIndexService.findByBundle()

    @GetMapping("/state/{id}")
    fun getState(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ): QueueStateResponse = dynamicIndexService.getState(id)

    @GetMapping("/state")
    fun getAllStates(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<QueueStateResponse> = dynamicIndexService.getAllStates()

    @PutMapping
    fun resetAll(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody items: List<DynamicIndexInfoResponse>,
    ): List<DynamicIndexInfoResponse> = dynamicIndexService.resetAll(items)
}

package com.cowave.search.jdbc.controller

import com.cowave.search.jdbc.dto.CreateJdbcRequest
import com.cowave.search.jdbc.dto.JdbcInfoResponse
import com.cowave.search.jdbc.dto.JdbcTestRequest
import com.cowave.search.jdbc.dto.JdbcTestResponse
import com.cowave.search.jdbc.dto.UpdateJdbcRequest
import com.cowave.search.jdbc.service.JdbcService
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/jdbc")
class JdbcController(
    private val jdbcService: JdbcService,
) {
    @GetMapping
    fun findAll(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<JdbcInfoResponse> = jdbcService.findAll(clusterId)

    @PostMapping
    fun create(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: CreateJdbcRequest,
    ): JdbcInfoResponse = jdbcService.create(clusterId, request)

    @PutMapping("/{id}")
    fun update(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
        @RequestBody request: UpdateJdbcRequest,
    ): JdbcInfoResponse = jdbcService.update(clusterId, id, request)

    @DeleteMapping("/{id}")
    fun delete(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ): ResponseEntity<Void> {
        jdbcService.delete(clusterId, id)
        return ResponseEntity.ok().build()
    }

    @PostMapping("/test")
    fun testConnection(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: JdbcTestRequest,
    ): JdbcTestResponse = jdbcService.testConnection(request)
}

package com.cowave.search.jdbc.service

import com.cowave.search.jdbc.dto.CreateJdbcRequest
import com.cowave.search.jdbc.dto.JdbcInfoResponse
import com.cowave.search.jdbc.dto.JdbcTestRequest
import com.cowave.search.jdbc.dto.JdbcTestResponse
import com.cowave.search.jdbc.dto.UpdateJdbcRequest
import com.cowave.search.jdbc.infrastructure.JdbcInfoRepository
import com.cowave.search.jdbc.model.JdbcInfo
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class JdbcService(
    private val jdbcInfoRepository: JdbcInfoRepository,
) {
    private val logger = LoggerFactory.getLogger(JdbcService::class.java)

    fun findAll(clusterId: String): List<JdbcInfoResponse> =
        jdbcInfoRepository
            .findAllByClusterId(clusterId)
            .map { it.toResponse() }

    fun create(
        clusterId: String,
        request: CreateJdbcRequest,
    ): JdbcInfoResponse {
        val entity =
            JdbcInfo(
                clusterId = clusterId,
                name = request.name,
                provider = request.provider,
                driver = request.driver,
                address = request.address,
                port = request.port,
                dbName = request.dbName,
                user = request.user,
                password = request.password,
                url = request.url,
                params = request.params,
            )
        return jdbcInfoRepository.save(entity).toResponse()
    }

    fun update(
        clusterId: String,
        id: String,
        request: UpdateJdbcRequest,
    ): JdbcInfoResponse {
        val entity =
            jdbcInfoRepository.findByClusterIdAndId(clusterId, id)
                ?: throw IllegalArgumentException("JDBC 설정을 찾을 수 없습니다: $id")
        request.name?.let { entity.name = it }
        request.provider?.let { entity.provider = it }
        request.driver?.let { entity.driver = it }
        request.address?.let { entity.address = it }
        request.port?.let { entity.port = it }
        request.dbName?.let { entity.dbName = it }
        request.user?.let { entity.user = it }
        request.password?.let { entity.password = it }
        request.url?.let { entity.url = it }
        request.params?.let { entity.params = it }
        return jdbcInfoRepository.save(entity).toResponse()
    }

    fun delete(
        clusterId: String,
        id: String,
    ) {
        jdbcInfoRepository.deleteByClusterIdAndId(clusterId, id)
    }

    fun testConnection(request: JdbcTestRequest): JdbcTestResponse =
        runCatching {
            Class.forName(request.driver)
            java.sql.DriverManager
                .getConnection(request.url, request.user, request.password)
                .use { true }
            JdbcTestResponse(success = true, message = "연결 성공")
        }.getOrElse { e ->
            logger.warn("JDBC 연결 테스트 실패: {}", e.message)
            JdbcTestResponse(success = false, message = e.message ?: "연결 실패")
        }

    private fun JdbcInfo.toResponse() =
        JdbcInfoResponse(
            id = id,
            clusterId = clusterId,
            name = name,
            provider = provider,
            driver = driver,
            address = address,
            port = port,
            dbName = dbName,
            user = user,
            url = url,
            params = params,
        )
}

