package com.cowave.search.tools.controller

import com.cowave.search.tools.service.ToolsService
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestHeader
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/tools")
class ToolsController(
    private val toolsService: ToolsService,
) {
    @GetMapping("/plugins")
    fun getPlugins(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<ToolsService.PluginInfo> = toolsService.getPlugins(clusterId)

    @PostMapping("/detail/analysis")
    fun analyzeText(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: ToolsService.AnalysisRequest,
    ): ToolsService.AnalysisResponse = toolsService.analyzeText(clusterId, request)
