    JDBC,
    HIVE,
    MONGODB,
    KAFKA,
    ICEBERG,
}

data class DataBatch(
    val rows: List<Map<String, Any?>>,
    val nextCursor: Any? = null,
    val hasMore: Boolean = false,
)

