package com.cowave.search.datasource.service

import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component
import java.sql.DriverManager
import java.sql.ResultSet

/**
 * JDBC 기반 DataSourceAdapter 구현체.
 * MySQL, Oracle, PostgreSQL, Hive, Impala 등 JDBC 호환 소스를 지원한다.
 */
@Component
class JdbcDataSourceAdapter : DataSourceAdapter {
    private val logger = LoggerFactory.getLogger(JdbcDataSourceAdapter::class.java)

    override val type: DataSourceType = DataSourceType.JDBC

    override fun testConnection(config: Map<String, String>): Boolean =
        runCatching {
            val driver = config["driver"] ?: error("driver 필수")
            val url = config["url"] ?: error("url 필수")
            Class.forName(driver)
            DriverManager
                .getConnection(url, config["user"], config["password"])
                .use { true }
        }.getOrElse { e ->
            logger.warn("JDBC 연결 테스트 실패: {}", e.message)
            false
        }

    override fun fetchBatch(
        config: Map<String, String>,
        query: String,
        batchSize: Int,
        cursor: Any?,
    ): DataBatch {
        val url = config["url"] ?: error("url 필수")
        val driver = config["driver"] ?: error("driver 필수")
        Class.forName(driver)
        val offset = (cursor as? Long) ?: 0L
        val pagedQuery = "$query LIMIT $batchSize OFFSET $offset"

        return DriverManager
            .getConnection(url, config["user"], config["password"])
            .use { conn ->
                conn.createStatement().use { stmt ->
                    stmt.executeQuery(pagedQuery).use { rs ->
                        val rows = resultSetToList(rs)
                        val nextOffset = offset + rows.size
                        DataBatch(
                            rows = rows,
                            nextCursor = if (rows.size == batchSize) nextOffset else null,
                            hasMore = rows.size == batchSize,
                        )
                    }
                }
            }
    }

    override fun estimateTotal(
        config: Map<String, String>,
        query: String,
    ): Long {
        val url = config["url"] ?: error("url 필수")
        val driver = config["driver"] ?: error("driver 필수")
        Class.forName(driver)
        val countQuery = "SELECT COUNT(*) FROM ($query) _count_t"

        return runCatching {
            DriverManager
                .getConnection(url, config["user"], config["password"])
                .use { conn ->
                    conn.createStatement().use { stmt ->
                        stmt.executeQuery(countQuery).use { rs ->
                            if (rs.next()) rs.getLong(1) else 0L
                        }
                    }
                }
        }.getOrElse { e ->
            logger.warn("건수 추정 실패: {}", e.message)
            -1L
        }
    }

    private fun resultSetToList(rs: ResultSet): List<Map<String, Any?>> {
        val meta = rs.metaData
        val columnCount = meta.columnCount
        val rows = mutableListOf<Map<String, Any?>>()
        while (rs.next()) {
            val row = mutableMapOf<String, Any?>()
            for (i in 1..columnCount) {
                row[meta.getColumnLabel(i)] = rs.getObject(i)
            }
            rows.add(row)
        }
        return rows
    }
}

