package com.cowave.search.aggregation.service

import com.cowave.search.aggregation.dto.AggregationBuildRequest
import com.cowave.search.aggregation.dto.AggregationNode
import com.cowave.search.aggregation.dto.AggregationType
import org.springframework.stereotype.Component

/**
 * AggregationNode 트리를 ES Aggregation DSL JSON 구조로 변환하는 빌더.
 * Tier 1: 기본 Bucket 6종 + Metric 7종 지원.
 */
@Component
class AggregationDslBuilder {
    fun build(request: AggregationBuildRequest): Map<String, Any> {
        val result = mutableMapOf<String, Any>()

        result["size"] = request.size

        if (request.query != null) {
            result["query"] = request.query
        }

        if (request.aggregations.isNotEmpty()) {
            result["aggs"] = buildAggregations(request.aggregations)
        }

        return result
    }

    private fun buildAggregations(nodes: List<AggregationNode>): Map<String, Any> {
        val aggs = mutableMapOf<String, Any>()
        for (node in nodes) {
            aggs[node.name] = buildSingleAggregation(node)
        }
        return aggs
    }

    private fun buildSingleAggregation(node: AggregationNode): Map<String, Any> {
        val aggBody = mutableMapOf<String, Any>()
        val typeName = node.type.toDslName()
        val config = mutableMapOf<String, Any>("field" to node.field)
        config.putAll(node.params.mapValues { it.value })

        // filter/filters는 field 기반이 아닌 query 기반
        when (node.type) {
            AggregationType.FILTER -> {
                config.remove("field")
                aggBody[typeName] = node.params["query"] ?: mapOf("match_all" to emptyMap<String, Any>())
            }
            AggregationType.FILTERS -> {
                config.remove("field")
                aggBody[typeName] = mapOf("filters" to (node.params["filters"] ?: emptyMap<String, Any>()))
            }
            AggregationType.COUNT -> {
                // value_count로 변환
                aggBody["value_count"] = config
            }
            else -> {
                aggBody[typeName] = config
            }
        }

        // 하위 집계 (재귀)
        if (node.subAggregations.isNotEmpty()) {
            aggBody["aggs"] = buildAggregations(node.subAggregations)
        }

        return aggBody
    }

    private fun AggregationType.toDslName(): String =
        when (this) {
            AggregationType.TERMS -> "terms"
            AggregationType.DATE_HISTOGRAM -> "date_histogram"
            AggregationType.HISTOGRAM -> "histogram"
            AggregationType.RANGE -> "range"
            AggregationType.FILTER -> "filter"
            AggregationType.FILTERS -> "filters"
            AggregationType.AVG -> "avg"
            AggregationType.SUM -> "sum"
            AggregationType.MIN -> "min"
            AggregationType.MAX -> "max"
            AggregationType.COUNT -> "value_count"
            AggregationType.CARDINALITY -> "cardinality"
            AggregationType.VALUE_COUNT -> "value_count"
        }
}

