package com.cowave.search.aggregation.service

import com.cowave.search.aggregation.dto.AggregationBuildRequest
import com.cowave.search.aggregation.dto.AggregationExecuteRequest
import com.cowave.search.aggregation.dto.AggregationExecuteResponse
import com.cowave.search.aggregation.dto.AggregationQueryResponse
import com.cowave.search.aggregation.dto.AggregationType
import com.cowave.search.aggregation.dto.FieldInfo
import com.cowave.search.aggregation.dto.SaveAggregationRequest
import com.cowave.search.aggregation.infrastructure.AggregationQueryRepository
import com.cowave.search.aggregation.model.AggregationQuery
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.fasterxml.jackson.databind.ObjectMapper
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.io.StringReader

@Service
class AggregationService(
    private val clientFactory: ElasticsearchClientFactory,
    private val aggregationQueryRepository: AggregationQueryRepository,
    private val aggregationDslBuilder: AggregationDslBuilder,
    private val objectMapper: ObjectMapper,
) {
    private val logger = LoggerFactory.getLogger(AggregationService::class.java)

    /** 빌더 JSON -> ES 쿼리 변환 (미리보기) */
    fun buildPreview(request: AggregationBuildRequest): Map<String, Any> =
        aggregationDslBuilder.build(request)

    /** ES에 집계 쿼리 직접 실행 */
    fun execute(
        clusterId: String,
        request: AggregationExecuteRequest,
    ): AggregationExecuteResponse {
        val client = clientFactory.getClient(clusterId)
        val searchBody = buildSearchBody(request)
        val response =
            client.search(
                { s ->
                    s
                        .index(request.index)
                        .withJson(StringReader(searchBody))
                },
                Any::class.java,
            )

        @Suppress("UNCHECKED_CAST")
        val aggsResult =
            objectMapper.convertValue(response.aggregations(), Map::class.java) as Map<String, Any>

        return AggregationExecuteResponse(
            took = response.took(),
            totalHits = response.hits().total()?.value() ?: 0,
            aggregations = aggsResult,
        )
    }

    /** 인덱스 매핑에서 집계 가능한 필드 목록 조회 */
    fun getAggregableFields(
        clusterId: String,
        index: String,
    ): List<FieldInfo> {
        val client = clientFactory.getClient(clusterId)
        val mappingResponse = client.indices().getMapping { it.index(index) }

        val fields = mutableListOf<FieldInfo>()
        mappingResponse.result().forEach { (_, indexMapping) ->
            extractFields(indexMapping.mappings().properties(), "", fields)
        }
        return fields
    }

    /** 집계 쿼리 템플릿 저장 */
    fun save(
        clusterId: String,
        request: SaveAggregationRequest,
    ): AggregationQueryResponse {
        val entity =
            AggregationQuery(
                clusterId = clusterId,
                name = request.name,
                description = request.description,
                index = request.index,
                queryJson = request.queryJson,
                aggregationJson = request.aggregationJson,
            )
        return aggregationQueryRepository.save(entity).toResponse()
    }

    /** 저장된 집계 템플릿 목록 */
    fun findAll(clusterId: String): List<AggregationQueryResponse> =
        aggregationQueryRepository
            .findAllByClusterId(clusterId)
            .map { it.toResponse() }

    /** 저장된 템플릿 상세 */
    fun findById(
        clusterId: String,
        id: String,
    ): AggregationQueryResponse =
        aggregationQueryRepository.findByClusterIdAndId(clusterId, id)?.toResponse()
            ?: throw IllegalArgumentException("집계 쿼리를 찾을 수 없습니다: $id")

    /** 저장된 템플릿 삭제 */
    fun delete(
        clusterId: String,
        id: String,
    ) {
        aggregationQueryRepository.deleteByClusterIdAndId(clusterId, id)
    }

    private fun buildSearchBody(request: AggregationExecuteRequest): String {
        val body = mutableMapOf<String, Any>()
        body["size"] = 0
        if (!request.queryJson.isNullOrBlank()) {
            @Suppress("UNCHECKED_CAST")
            body["query"] = objectMapper.readValue(request.queryJson, Map::class.java) as Map<String, Any>
        }
        @Suppress("UNCHECKED_CAST")
        body["aggs"] = objectMapper.readValue(request.aggregationJson, Map::class.java) as Map<String, Any>
        return objectMapper.writeValueAsString(body)
    }

    private fun extractFields(
        properties: Map<String, co.elastic.clients.elasticsearch._types.mapping.Property>,
        prefix: String,
        result: MutableList<FieldInfo>,
    ) {
        properties.forEach { (name, prop) ->
            val fullName = if (prefix.isEmpty()) name else "$prefix.$name"
            val typeName = prop._kind().name.lowercase()
            val aggregatable = typeName in AGGREGATABLE_TYPES
            if (aggregatable) {
                result.add(
                    FieldInfo(
                        name = fullName,
                        type = typeName,
                        aggregatable = true,
                        supportedAggregations = getSupportedAggregations(typeName),
                    ),
                )
            }
        }
    }

    private fun getSupportedAggregations(typeName: String): List<AggregationType> =
        when (typeName) {
            "keyword" -> listOf(AggregationType.TERMS, AggregationType.CARDINALITY, AggregationType.VALUE_COUNT)
            "long", "integer", "short", "byte", "double", "float", "half_float", "scaled_float" ->
                listOf(
                    AggregationType.AVG,
                    AggregationType.SUM,
                    AggregationType.MIN,
                    AggregationType.MAX,
                    AggregationType.CARDINALITY,
                    AggregationType.HISTOGRAM,
                    AggregationType.RANGE,
                    AggregationType.VALUE_COUNT,
                )
            "date" ->
                listOf(
                    AggregationType.DATE_HISTOGRAM,
                    AggregationType.MIN,
                    AggregationType.MAX,
                    AggregationType.RANGE,
                    AggregationType.CARDINALITY,
                    AggregationType.VALUE_COUNT,
                )
            "boolean" -> listOf(AggregationType.TERMS, AggregationType.VALUE_COUNT)
            "ip" -> listOf(AggregationType.TERMS, AggregationType.CARDINALITY)
            else -> emptyList()
        }

    private fun AggregationQuery.toResponse() =
        AggregationQueryResponse(
            id = id,
            clusterId = clusterId,
            name = name,
            description = description,
            index = index,
            queryJson = queryJson,
            aggregationJson = aggregationJson,
            createdBy = createdBy,
            createdAt = createdAt.toString(),
            updatedAt = updatedAt.toString(),
        )

    companion object {
        private val AGGREGATABLE_TYPES =
            setOf(
                "keyword",
                "long",
                "integer",
                "short",
                "byte",
                "double",
                "float",
                "half_float",
                "scaled_float",
                "date",
                "boolean",
                "ip",
            )
    }
}

